const char *file_path = "/tmp/data.bin";
const char *link_path = "/tmp/link_to_data";
const char *attr_name = "user.checksum";
int fd = 5; // Open file descriptor
int ret;

// Remove attribute from regular file
ret = removexattr(file_path, attr_name);

// Remove attribute from symbolic link itself
ret = lremovexattr(link_path, attr_name);

// Remove attribute using an open FD
ret = fremovexattr(fd, attr_name);

if (ret == -1) {
    // Common error: ENODATA (attribute not found)
    if (errno != ENODATA) {
        // Handle other failures
    }
}
